/* -----------------------------------------------------------------------
 * touch_filter.c
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29 Oct 2026 for Tony's display/UI subsystem (best-ui).
 * BJT2 Sound Modulating Toy — Touch Press Filter Implementation
 * Subsystem: Display/UI (Tony). Generative AI was used to assist.
 *
 * Both rules are written out in touch_filter.h. The filter keeps only
 * whether a press is down and how many RELEASED samples it has had since
 * its last PRESSED one, so its state fits in two bytes.
 *
 * No HAL functions are called. This file compiles on any host.
 * ----------------------------------------------------------------------- */

#include "touch_filter.h"
#include "touch_calibration.h"
#include <stddef.h>

/* |a - b| with no signed intermediate */
static uint16_t spread(uint16_t a, uint16_t b)
{
    return (a > b) ? (uint16_t)(a - b) : (uint16_t)(b - a);
}

/* -----------------------------------------------------------------------
 * touch_classify
 * The PRESSED test is the one the firmware applied before this module;
 * what changed is that a failed test is no longer always a release.
 * ----------------------------------------------------------------------- */
touch_sample_t touch_classify(uint16_t x1, uint16_t y1,
                              uint16_t x2, uint16_t y2)
{
    bool first  = touch_is_pressed(x1, y1);
    bool second = touch_is_pressed(x2, y2);

    if (!first && !second) {
        return TOUCH_SAMPLE_RELEASED;
    }
    if (first && second &&
        spread(x1, x2) <= TOUCH_SPREAD_MAX &&
        spread(y1, y2) <= TOUCH_SPREAD_MAX) {
        return TOUCH_SAMPLE_PRESSED;
    }
    return TOUCH_SAMPLE_UNSURE;
}

/* -----------------------------------------------------------------------
 * touch_filter_init
 * ----------------------------------------------------------------------- */
void touch_filter_init(touch_filter_t *f)
{
    if (f == NULL) {
        return;
    }
    f->down     = 0U;
    f->released = 0U;
}

/* -----------------------------------------------------------------------
 * touch_filter_update
 * ----------------------------------------------------------------------- */
touch_action_t touch_filter_update(touch_filter_t *f, touch_sample_t sample)
{
    if (f == NULL) {
        return TOUCH_ACT_NONE;
    }

    switch (sample) {

        case TOUCH_SAMPLE_PRESSED:
            f->released = 0U;
            if (f->down == 0U) {
                f->down = 1U;               /* a new press: its one tap */
                return TOUCH_ACT_TAP;
            }
            return TOUCH_ACT_HELD;

        case TOUCH_SAMPLE_RELEASED:
            if (f->down != 0U) {
                f->released++;
                if (f->released >= TOUCH_RELEASE_SAMPLES) {
                    /* Off the glass long enough: the press is over */
                    f->down     = 0U;
                    f->released = 0U;
                }
            }
            return TOUCH_ACT_NONE;

        default:
            /* UNSURE (or not a touch_sample_t): neither starts nor ends
             * a press, and gives no position */
            return TOUCH_ACT_NONE;
    }
}
